// Category A — a <form> that wraps multiple fields. Propagates RAC's validation context
// (validationErrors, etc.) to child fields. Owns only a minimal look (vertical layout gap).
import { Form as AriaForm } from "react-aria-components";
import type { FormProps as AriaFormProps } from "react-aria-components";
import type { Ref } from "react";
import "./Form.css";

export interface FormProps extends Omit<AriaFormProps, "className"> {
  /**
   * The form's submission is in flight: a submit while pending is ignored, and the form is marked
   * busy. Pass the same flag the submit Button takes. A pending Button stops being a submit button
   * (React Aria), so it cannot block a second submit by itself: a form with one text field still
   * submits on Enter (HTML implicit submission).
   */
  isPending?: boolean;
  /** Additional class (optional). sd-form is always preserved. */
  className?: string;
  /** Forwarded to the underlying <form> DOM node. */
  ref?: Ref<HTMLFormElement>;
}

export function Form({ isPending, onSubmit, className, ref, ...props }: FormProps) {
  return (
    <AriaForm
      {...props}
      ref={ref}
      // Set only while pending, after the spread, so an `aria-busy` a consumer passes otherwise stays.
      {...(isPending ? { "aria-busy": true } : {})}
      onSubmit={(event) => {
        if (isPending) {
          event.preventDefault();
          return;
        }
        onSubmit?.(event);
      }}
      className={className ? `sd-form ${className}` : "sd-form"}
    />
  );
}

.sd-form {
  display: flex;
  flex-direction: column;
  gap: var(--sd-form-gap);
}
